# Generates geographiclib_geodesic.csv from GeographicLib (pure-Python port, MIT).
# Run: python generate_geodesic_reference.py geographiclib_geodesic.csv  (needs: pip install geographiclib)
import sys, random
from geographiclib.geodesic import Geodesic
OUT = sys.argv[1]
g = Geodesic.WGS84
rng = random.Random(2013)
lines = []
# Inverse problems: I;lat1;lon1;lat2;lon2;s12;azi1;azi2
pairs = [
    (0.5, 0.0, -0.5, 179.7),        # nearly antipodal, Vincenty's failure region
    (0.0, 0.0, 0.0, 180.0),         # equatorial antipodes
    (0.0, 0.0, 10.0, 170.0),
    (0.0, 10.0, 0.0, 20.0),         # equatorial
    (30.0, 0.0, 30.0, 90.0),
    (10.0, 0.0, 80.0, 0.0),         # meridian
    (-45.0, 170.0, 45.0, -170.0),
    (89.9, 0.0, -89.9, 180.0),      # near-polar antipodes
    (51.5, -0.1, 48.85, 2.35),      # London to Paris
    (-37.8, 144.9, -33.9, 151.2),   # Melbourne to Sydney
    (40.0, -74.0, 35.7, 139.7),
    (10.0, 10.0, 10.0, 10.0000001), # very short
    (0.0, 0.0, 1e-9, 1e-9),
]
for _ in range(300):
    lat1 = rng.uniform(-90, 90); lon1 = rng.uniform(-180, 180)
    if rng.random() < 0.3:
        lat2 = -lat1 + rng.uniform(-0.6, 0.6); lon2 = lon1 + 180 + rng.uniform(-0.6, 0.6)
        lat2 = max(-90, min(90, lat2)); lon2 = ((lon2 + 180) % 360) - 180
    else:
        lat2 = rng.uniform(-90, 90); lon2 = rng.uniform(-180, 180)
    pairs.append((lat1, lon1, lat2, lon2))
for lat1, lon1, lat2, lon2 in pairs:
    r = g.Inverse(lat1, lon1, lat2, lon2)
    lines.append(f"I;{lat1:.12f};{lon1:.12f};{lat2:.12f};{lon2:.12f};{r['s12']:.9f};{r['azi1']:.12f};{r['azi2']:.12f}")
# Direct problems: D;lat1;lon1;azi1;s12;lat2;lon2;azi2
for _ in range(300):
    lat1 = rng.uniform(-89, 89); lon1 = rng.uniform(-180, 180)
    azi1 = rng.uniform(-360, 360); s12 = rng.uniform(0, 2.0e7)
    r = g.Direct(lat1, lon1, azi1, s12)
    lines.append(f"D;{lat1:.12f};{lon1:.12f};{azi1:.12f};{s12:.6f};{r['lat2']:.12f};{r['lon2']:.12f};{r['azi2']:.12f}")
with open(OUT, "w", newline="\n") as f:
    f.write("# GeographicLib 2.1 (Karney), WGS84. I = inverse (lat1;lon1;lat2;lon2;s12;azi1;azi2),\n")
    f.write("# D = direct (lat1;lon1;azi1;s12;lat2;lon2;azi2). Generated by generate_geodesic_reference.py.\n")
    f.write("\n".join(lines) + "\n")
print("rows", len(lines))
